"use strict";(globalThis.webpackChunkgrc||=[]).push([[94864],{12201(e){e.exports=JSON.parse('[{"citeKey":"cernuda2024jarvis","slug":"cernuda-2024-jarvis-3b52","title":"Jarvis: Towards a Shared, User-Friendly, and Reproducible, I/O Infrastructure.","authors":["J. Cernuda","L. Logan","N. Lewis","S. Byna","X.-H. Sun","A. Kougkas"],"venue":"The International Parallel Data Systems Workshop (PDSW\'24)","type":"Workshop","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"abstract":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters. However, computing environments for developing tools to harness these technologies are not easily available to researchers. This work showcases the need for a new high-pace, heterogeneous I/O research cluster and presents a novel software deployment framework named Jarvis to manage its hardware diversity. Jarvis is an extensible Python framework that allows users to create Packages that deploy, manage, and monitor software, including complex applications (e.g., scientific simulations), support tools (e.g., Darshan, GDB), and storage systems (e.g., Lustre, DAOS). These packages can be combined to form complex deployment Pipelines. To ensure pipelines are portable across hardware, Jarvis defines a novel Resource Graph schema file, which is a snapshot of a cluster\'s machine-specific information. This schema can be queried by Jarvis packages to deploy software across diverse hardware compositions with minimal user effort. Index Terms-deployment, HPC, hardware abstraction, resource management, I/O, Python","hasAbstract":true,"lede":"Hardware is becoming increasingly heterogeneous in modern high-performance computing clusters.","links":{"pdf":"https://grc.iit.edu/papers/2024/cernuda-2024-jarvis-3b52.pdf"},"tags":["Deployment","HPC","Hardware Abstraction","I/O","Python","Resource Management"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2024tunio","slug":"rajesh-2024-tunio-05a8","title":"TunIO: An AI-powered Framework for Optimizing HPC I/O","authors":["N. Rajesh","K. Bateman","S. Byna","J. L. Bez","A. Kougkas","X.-H. Sun"],"venue":"The 38th IEEE International Parallel & Distributed Processing Symposium (IPDPS 2024)","type":"Conference","entryType":"inproceedings","date":"May, 2024","year":2024,"era":"iit","month":5,"doi":"10.1109/ipdps57955.2024.00050","abstract":"I/O operations are a known performance bottleneck of HPC applications. To achieve good performance, users often employ an iterative multistage tuning process to find an optimal I/O stack configuration. However, an I/O stack contains multiple layers, such as high-level I/O libraries, I/O middleware, and parallel file systems, and each layer has many parameters. These parameters and layers are entangled and influenced by each other. The tuning process is time-consuming and complex. In this work, we present TunIO, an AI- powered I/O tuning framework that implements several techniques to balance the tuning cost and performance gain, including tuning the high- impact parameters first. Furthermore, TunIO analyzes the application source code to extract its I/O kernel while retaining all statements necessary to perform I/O. It utilizes a smart selection of high-impact configuration parameters of the given tuning objective. Finally, it uses a novel Reinforcement Learning (RL)-driven early stopping mechanism to balance the cost and performance gain. Experimental results show that TunIO leads to a reduction of up to \u2248 73% in tuning time while achieving the same performance gain when compared to H5Tuner. It achieves a significant performance gain/cost of 208.4 MBps/min (I/O bandwidth for each minute spent in tuning) over existing approaches under our testing. Index Terms-AI-powered I/O tuning, storage stack tuning, autotun- ing, source code transformations, and I/O performance optimization","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/rajesh-2024-tunio-05a8.pdf"},"tags":["AI for I/O","I/O Stack Tuning"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"DOE","award":"DE-SC0023263","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2021featurereduction","slug":"rajesh-2021-feature-reduction-4823","title":"Feature Reduction of Darshan Counters Using Evolutionary Algorithms","authors":["N. Rajesh","Q. Koziol","S. Byna","H. Tang","J. L. Bez","A. Kougkas","X.-H. Sun"],"venue":"The 2021 International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'21), November 14\u201319, 2021","type":"Poster","entryType":"misc","date":"November, 2021","year":2021,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2021/rajesh-2021-feature-reduction-4823.pdf","poster":"https://grc.iit.edu/papers/2021/rajesh-2021-feature-reduction-4823-poster.pdf"},"tags":["Feature Reduction","Evolutionary Algorithms","Darshan"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yin2012boostingapplication","slug":"yin-2012-boosting-application-9c3f","title":"Boosting Application-Specific Parallel I/O Optimization Using IOSIG","authors":["Y. Yin","S. Byna","H. Song","X.-H. Sun","R. Thakur"],"venue":"IEEE/ACM International Symposium on Cluster, Cloud and Grid Computing (CCGrid), Ottawa, Canada","type":"Conference","entryType":"inproceedings","date":"May, 2012","year":2012,"era":"iit","month":5,"doi":"10.1109/ccgrid.2012.136","abstract":"Many scientific applications spend a significant portion of their execution time in accessing data from files. Various optimization techniques exist to improve data access performance, such as data prefetching and data layout optimization. However, optimization process is usually a difficult task due to the complexity involved in understanding I/O behavior. Tools that can help simplify the optimization process have a significant importance. In this paper, we introduce a tool, called IOSIG, for providing a better understanding of parallel I/O accesses and information to be used for optimization techniques. The tool enables tracing parallel I/O calls of an application and analyzing the collected information to provide a clear understanding of I/O behavior of the application. We show that performance overheads of the tool in trace collection and analysis are negligible. The analysis step creates I/O signatures that various optimizations can use for improving I/O performance. I/O signatures are compact, easy-to-understand, and parameterized representations containing data access pattern information such as size, strides between consecutive accesses, repetition, timing, etc. The signatures include local I/O behavior for each process and global behavior for an overall application. We illustrate the usage of the IOSIG tool in data prefetching and data layout optimizations.","hasAbstract":true,"lede":"We introduce a tool, called IOSIG, for providing a better understanding of parallel I/O accesses and information to be used for optimization techniques.","links":{"pdf":"https://grc.iit.edu/papers/2012/yin-2012-boosting-application-9c3f.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"sun2009modelingdata","slug":"sun-2009-modeling-data-b47c","title":"Modeling Data Access Contention in Multicore Architectures","authors":["X.-H. Sun","S. Byna","D. J. Holmgren"],"venue":"The Fifteenth International Conference on Parallel and Distributed Systems (ICPADS\'09), Shenzhen, China","type":"Conference","entryType":"inproceedings","date":"December, 2009","year":2009,"era":"iit","month":12,"doi":"10.1109/icpads.2009.121","hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2009/sun-2009-modeling-data-b47c.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"byna2009taxonomydata","slug":"byna-2009-taxonomy-data-5e3a","title":"Taxonomy of data prefetching for multicore processors","authors":["S. Byna","Y. Chen","X.-H. Sun"],"venue":"Journal of Computer Science and Technology, vol. 24, no. 3, pp. 405-417","type":"Journal","entryType":"article","date":"May, 2009","year":2009,"era":"iit","month":5,"doi":"10.1007/s11390-009-9233-4","abstract":"Data prefetching is an effective data access latency hiding technique to mask the CPU stall caused by cache misses and to bridge the performance gap between processor and memory. With hardware and/or software support, data prefetching brings data closer to a processor before it is actually needed. Many prefetching techniques have been developed for single-core processors. Recent developments in processor technology have brought multicore processors into mainstream. While some of the single-core prefetching techniques are directly applicable to multicore processors, numerous novel strategies have been proposed in the past few years to take advantage of multiple cores. This paper aims to provide a comprehensive review of the state-of-the-art prefetching techniques, and proposes a taxonomy that classifies various design concerns in developing a prefetching strategy, especially for multicore processors. We compare various existing methods through analysis as well.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2009/byna-2009-taxonomy-data-5e3a.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"fang2009coreaware","slug":"fang-2009-core-aware-0364","title":"Core-Aware Memory Access Scheduling Schemes","authors":["Z. Fang","X.-H. Sun","Y. Chen","S. Byna"],"venue":"The IEEE International Parallel & Distributed Processing Symposium (IPDPS\'09), Rome, Italy","type":"Conference","entryType":"inproceedings","date":"May, 2009","year":2009,"era":"iit","month":5,"doi":"10.1109/ipdps.2009.5161013","abstract":"Multi-core processors have changed the conventional hardware structure and require a rethinking of system scheduling and resource management to utilize them efficiently. However, current multi-core systems are still using conventional single-core memory scheduling. In this study, we investigate and evaluate traditional memory access scheduling techniques, and propose a core-aware memory scheduling for multi-core environments. Since memory requests from the same source exhibit better locality, it is reasonable to schedule the requests by taking the source of the requests into consideration. Motivated from this principle of locality, we propose two core-aware policies based on traditional bank-first and row-first schemes. Simulation results show that the core-aware policies can effectively improve the performance. Compared with the bank-first and row-first policies, the proposed core-aware policies reduce the execution time of certain NAS Parallel Benchmarks by up to 20% in running the benchmarks separately, and by 11% in running them concurrently.","hasAbstract":true,"lede":"Motivated from this principle of locality, we propose two core-aware policies based on traditional bank-first and row-first schemes.","links":{"pdf":"https://grc.iit.edu/papers/2009/fang-2009-core-aware-0364.pdf","slides":"https://grc.iit.edu/papers/2009/fang-2009-core-aware-0364-slides.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"piccoli2008latticeqcd","slug":"piccoli-2008-lattice-qcd-08d3","title":"Lattice QCD Workflows: A Case Study","authors":["L. Piccoli","J. B. Kowalkowski","J. N. Simone","X.-H. Sun","H. Jin","D. J. Holmgren","N. Seenu","A. G. Singh","S. Byna","D. J. Holmgren"],"venue":"3rd International Workshop on Scientific Workflows and Business Workflow Standards in e-Science (SWBES)","type":"Workshop","entryType":"inproceedings","date":"December, 2008","year":2008,"era":"iit","month":12,"doi":"10.1109/escience.2008.168","abstract":"This paper discusses the application of existing workflow management systems to a real world science application (LQCD). Typical workflows and execution environment used in production are described. Requirements for the LQCD production system are discussed. The workflow management systems Askalon and Swift were tested by implementing the LQCD workflows and evaluated against the requirements. We report our findings and future work.","hasAbstract":true,"lede":"This paper discusses the application of existing workflow management systems to a real world science application (LQCD).","links":{"pdf":"https://grc.iit.edu/papers/2008/piccoli-2008-lattice-qcd-08d3.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"byna2008parallelio","slug":"byna-2008-parallel-io-6da7","title":"Parallel I/O Prefetching Using MPI File Caching and I/O Signatures","authors":["S. Byna","Y. Chen","X.-H. Sun","R. Thakur","W. D. Gropp"],"venue":"The ACM/IEEE SuperComputing Conference (SC\'08)","type":"Conference","entryType":"inproceedings","date":"November, 2008","year":2008,"era":"iit","month":11,"doi":"10.1109/sc.2008.5213604","abstract":"Parallel I/O prefetching is considered to be effective in improving I/O performance. However, the effectiveness depends on determining patterns among future I/O accesses swiftly and fetching data in time, which is difficult to achieve in general. In this study, we propose an I/O signature-based prefetching strategy. The idea is to use a predetermined I/O signature of an application to guide prefetching. To put this idea to work, we first derived a classification of patterns and introduced a simple and effective signature notation to represent patterns. We then developed a toolkit to trace and generate I/O signatures automatically. Finally, we designed and implemented a thread-based client-side collective prefetching cache layer for MPI-IO library to support prefetching. A prefetching thread reads I/O signatures of an application and adjusts them by observing I/O accesses at runtime. Experimental results show that the proposed prefetching method improves I/O performance significantly for applications with complex patterns.","hasAbstract":true,"lede":"In this study, we propose an I/O signature-based prefetching strategy.","links":{"pdf":"https://grc.iit.edu/papers/2008/byna-2008-parallel-io-6da7.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"chen2008hidingio","slug":"chen-2008-hiding-io-d98b","title":"Hiding I/O Latency with Pre-execution Prefetching for Parallel Applications","authors":["Y. Chen","S. Byna","X.-H. Sun","R. Thakur","W. D. Gropp"],"venue":"The ACM/IEEE SuperComputing Conference (SC\'08) Best paper award finalist","type":"Conference","entryType":"inproceedings","date":"November, 2008","year":2008,"era":"iit","month":11,"doi":"10.1109/sc.2008.5213209","abstract":"Parallel applications are usually able to achieve high computational performance but suffer from large latency in I/O accesses. I/O prefetching is an effective solution for masking the latency. Most of existing I/O prefetching techniques, however, are conservative and their effectiveness is limited by low accuracy and coverage. As the processor-I/O performance gap has been increasing rapidly, data-access delay has become a dominant per- formance bottleneck. We argue that it is time to revisit the \\"I/O wall\\" problem and trade the excessive computing power with data-access speed. We propose a novel pre-execution approach for masking I/O latency. We describe the pre-execution I/O prefetching framework, the pre-execution thread construction methodology, the underlying library support, and the proto- type implementation in the ROMIO MPI-IO implementation in MPICH2. Preliminary experiments show that the pre-execution approach is promising in reducing I/O access latency and has real potential.","hasAbstract":true,"lede":"We propose a novel pre-execution approach for masking I/O latency.","links":{"pdf":"https://grc.iit.edu/papers/2008/chen-2008-hiding-io-d98b.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"chen2008exploringparallel","slug":"chen-2008-exploring-parallel-4054","title":"Exploring Parallel I/O Concurrency with Speculative Prefetching","authors":["Y. Chen","S. Byna","X.-H. Sun","R. Thakur","W. D. Gropp"],"venue":"The 37th International Conference on Parallel Processing (ICPP\'08)","type":"Conference","entryType":"inproceedings","date":"September, 2008","year":2008,"era":"iit","month":9,"doi":"10.1109/icpp.2008.54","hasAbstract":false,"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"sun2008scalablecomputing","slug":"sun-2008-scalable-computing-9362","title":"Scalable Computing in Multicore Era","authors":["X.-H. Sun","Y. Chen","S. Byna"],"venue":"The International Symposium on Parallel Algorithms, Architectures and Programming (PAAP\'08)","type":"Conference","entryType":"inproceedings","date":"September, 2008","year":2008,"era":"iit","month":9,"hasAbstract":false,"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"byna2008taxonomydata","slug":"byna-2008-taxonomy-data-49d6","title":"A Taxonomy of Data Prefetching Mechanisms","authors":["S. Byna","Y. Chen","X.-H. Sun"],"venue":"The International Symposium on Parallel Architectures, Algorithms, and Networks (I-SPAN)","type":"Conference","entryType":"inproceedings","date":"May, 2008","year":2008,"era":"iit","month":5,"doi":"10.1109/i-span.2008.24","abstract":"Data prefetching has been considered an effective way to mask data access latency caused by cache misses and to bridge the performance gap between processor and memory. With hardware and/or software support, data prefetching brings data closer to a processor before it is actually needed. Many prefetching techniques have been proposed in the last few years to reduce data access latency by taking advantage of multi-core architectures. In this paper, we propose a taxonomy that classifies various design concerns in developing a prefetching strategy. We discuss various prefetching strategies and issues that have to be considered in designing a prefetching strategy for multi-core processors.","hasAbstract":true,"lede":"We propose a taxonomy that classifies various design concerns in developing a prefetching strategy.","links":{"pdf":"https://grc.iit.edu/papers/2008/byna-2008-taxonomy-data-49d6.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"chen2007dataaccess","slug":"chen-2007-data-access-75aa","title":"Data Access History Cache and Associated Data Prefetching Mechanisms","authors":["Y. Chen","S. Byna","X.-H. Sun"],"venue":"The ACM/IEEE SuperComputing Conf. 2007 (SC\'07)","type":"Conference","entryType":"inproceedings","date":"November, 2007","year":2007,"era":"iit","month":11,"doi":"10.1145/1362622.1362651","abstract":"Data prefetching is an effective way to bridge the increasing performance gap between processor and memory. As computing power is increasing much faster than memory performance, we suggest that it is time to have a dedicated cache to store data access histories and to serve prefetching to mask data access latency effectively. We thus propose a new cache structure, named Data Access History Cache (DAHC), and study its associated prefetching mechanisms. The DAHC behaves as a cache for recent reference information instead of as a traditional cache for instructions or data. Theoretically, it is capable of supporting many well known history-based prefetching algorithms, especially adaptive and aggressive approaches. We have carried out simulation experiments to validate DAHC design and DAHC-based data prefetching methodologies and to demonstrate performance gains. The DAHC provides a practical approach to reaping data prefetching benefits and its associated prefetching mechanisms are proven more effective than traditional approaches.","hasAbstract":true,"lede":"Data prefetching is an effective way to bridge the increasing performance gap between processor and memory.","links":{"pdf":"https://grc.iit.edu/papers/2007/chen-2007-data-access-75aa.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"sun2007improvingdata","slug":"sun-2007-improving-data-1868","title":"Improving Data Access Performance with Server Push Architecture","authors":["X.-H. Sun","S. Byna","Y. Chen"],"venue":"The NSF Next Generation Software Program Workshop (in conjunction with IPDPS \'07)","type":"Workshop","entryType":"inproceedings","date":"March, 2007","year":2007,"era":"iit","month":3,"doi":"10.1109/ipdps.2007.370511","abstract":"Data prefetching, where data is fetched before CPU demands for it, has been considered as an effective solution to mask data access latency. However, the current client-initiated prefetching strategies do not work well for applications with complex, non-contiguous data access patterns. While technology advances continue to enlarge the gap between computing and data access performance, trading computing power for data access delay has become a natural choice. We propose a server- based data-push approach. In this server-push architecture, a dedicated server named Data Push Server (DPS) initiates and proactively pushes data closer to the client in time. We present the DPS architecture and study the issues such as what data to fetch, when to fetch, how to push, and data access modeling.","hasAbstract":true,"lede":"We propose a server- based data-push approach.","links":{"pdf":"https://grc.iit.edu/papers/2007/sun-2007-improving-data-1868.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"sun2007serverbased","slug":"sun-2007-server-based-8c74","title":"Server-based Data Push Architecture for Multi-processor Environments","authors":["X.-H. Sun","S. Byna","Y. Chen"],"venue":"Journal of Computer Science and Technology (JCST), vol. 22, no. 5, pp. 641-652","type":"Journal","entryType":"article","date":"January, 2007","year":2007,"era":"iit","month":1,"doi":"10.1007/s11390-007-9090-y","abstract":"Data access delay is a major bottleneck in utilizing current high-end computing (HEC) machines. Prefetch- ing, where data is fetched before CPU demands for it, has been considered as an effective solution to masking data access delay. However, current client-initiated prefetching strategies, where a computing processor initiates prefetching instructions, have many limitations. They do not work well for applications with complex, non-contiguous data access patterns. While technology advances continue to increase the gap between computing and data access performance, trading computing power for reducing data access delay has become a natural choice. In this paper, we present a server- based data-push approach and discuss its associated implementation mechanisms. In the server-push architecture, a dedicated server called Data Push Server (DPS) initiates and proactively pushes data closer to the client in time. Issues, such as what data to fetch, when to fetch, and how to push are studied. The SimpleScalar simulator is modified with a dedicated prefetching engine that pushes data for another processor to test DPS based prefetching. Simulation results show that L1 Cache miss rate can be reduced by up to 97% (71% on average) over a superscalar processor for SPEC CPU2000 benchmarks that have high cache miss rates.","hasAbstract":true,"lede":"We present a server- based data-push approach and discuss its associated implementation mechanisms.","links":{"pdf":"https://grc.iit.edu/papers/2007/sun-2007-server-based-8c74.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"byna2006automaticmemory","slug":"byna-2006-automatic-memory-49c5","title":"Automatic Memory Optimizations for Improving MPI Derived Datatype Performance","authors":["S. Byna","X.-H. Sun","R. Thakur","W. D. Gropp"],"venue":"13th The European PVM/MPI Conference, Bonn, Germany, Lecture Notes in Computer Science, Springer","type":"Conference","entryType":"inproceedings","date":"September, 2006","year":2006,"era":"iit","month":9,"doi":"10.1007/11846802_36","abstract":"MPI derived datatypes allow users to describe noncontiguous memory layout and communicate noncontiguous data with a single communication function. This powerful feature enables an MPI implementation to optimize the transfer of noncontiguous data. In practice, however, many implementations of MPI derived datatypes perform poorly, which makes application developers avoid using this feature. In this paper, we present a technique to automatically select templates that are optimized for memory performance based on the access pattern of derived datatypes. We implement this mechanism in the MPICH2 source code. The performance of our implementation is compared to well-written manual packing/unpacking routines and original MPICH2 implementation. We show that performance for various derived datatypes is significantly improved and comparable to that of optimized manual routines.","hasAbstract":true,"lede":"We present a technique to automatically select templates that are optimized for memory performance based on the access pattern of derived datatypes.","links":{"pdf":"https://grc.iit.edu/papers/2006/byna-2006-automatic-memory-49c5.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"byna2006memoryservers","slug":"byna-2006-memory-servers-035f","title":"Memory Servers: A Scope of SOA for High-End Computing","authors":["S. Byna","X.-H. Sun","R. Nakhoul"],"venue":"The IEEE Service Computing Conference (SCC) 2006, Chicago","type":"Conference","entryType":"inproceedings","date":"September, 2006","year":2006,"era":"iit","month":9,"doi":"10.1109/scc.2006.67","abstract":"The expanding gap between microprocessor and disk performance has initiated new techniques of providing memory as a service in high-end computing (HEC). Although the processor and disk densities have improved over the last decades, the improvement of disk performance is inferior to that of processors, which is causing a bottleneck for HEC. With the rapid growth of network technology for cluster computers, the idea of accessing memory of an idle peer node has proven to be faster than accessing a disk. With this motivation, many researchers developed systems that offer idle memory as a service. In this paper, we present a brief survey of various systems that offer memory service in improving the disk access performance and discuss the scope of applying service oriented architecture (SOA) for HEC.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2006/byna-2006-memory-servers-035f.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"byna2005isolatingcosts","slug":"byna-2005-isolating-costs-496d","title":"Isolating costs in shared memory communication buffering","authors":["S. Byna","K. Cameron","X.-H. Sun"],"venue":"Parallel Processing Letters, vol. 15, no. 4, pp. 357-365","type":"Journal","entryType":"article","date":"January, 2005","year":2005,"era":"iit","month":1,"doi":"10.1142/s0129626405002271","abstract":"ABSTRACT Communication in parallel applications is a combination of data transfers internally at a source or destination and across the network. Previous research focused on quantify- ing network transfer costs has indirectly resulted in reduced overall communication cost. Optimized data transfer from source memory to the network interface has received less attention. In shared memory systems, such memory-to-memory transfers dominate com- munication cost. In distributed memory systems, memory-to-network interface transfers grow in significance as processor and network speeds increase at faster rates than mem- ory latency speeds. Our objective is to minimize the cost of internal data transfers. The following examples illustrating the impact of memory transfers on communication, we present a methodology for classifying the effects of data size and data distribution on hardware, middleware, and application software performance. This cost is quantified using hardware counter event measurements on the SGI Origin 2000. For the SGI O2K, we empirically identify the cost caused by just copying data from one buffer to another and the middleware overhead. We use MPICH in our experiments, but our techniques are generally applicable to any communication implementation.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2005/byna-2005-isolating-costs-496d.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"byna2004predictingmemory","slug":"byna-2004-predicting-memory-696b","title":"Predicting the Memory-Access Cost Based on Data Access Patterns","authors":["S. Byna","X.-H. Sun","W. D. Gropp","R. Thakur"],"venue":"The IEEE International Conference on Cluster Computing, San Diego","type":"Conference","entryType":"inproceedings","date":"September, 2004","year":2004,"era":"iit","month":9,"doi":"10.1109/CLUSTR.2004.1392630","abstract":"Improving memory performance at software level is more effective in reducing the rapidly expanding gap between processor and memory performance. Loop transformations (e.g. loop unrolling, loop tiling) and array restructuring optimizations improve the memory performance by increasing the locality of memory accesses. To find the best optimization parameters at runtime, we need a fast and simple analytical model to predict the memory access cost. Most of the existing models are complex and impractical to be integrated in the runtime tuning systems. In this paper, we propose a simple, fast and reasonably accurate model that is capable of predicting the memory access cost based on a wide range of data access patterns that appear in many scientific applications.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2004/byna-2004-predicting-memory-696b.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"byna2003improvingperformance","slug":"byna-2003-improving-performance-468e","title":"Improving the Performance of MPI Derived Datatypes by Optimizing Memory-Access Cost","authors":["S. Byna","W. D. Gropp","X.-H. Sun","R. Thakur"],"venue":"The IEEE International Conference on Cluster Computing, 2003, Hong Kong","type":"Conference","entryType":"inproceedings","date":"December, 2003","year":2003,"era":"iit","month":12,"doi":"10.1109/clustr.2003.1253341","abstract":"The MPI Standard supports derived datatypes, which allow users to describe noncontiguous memory layout and communicate noncontiguous data with a single communication function. This feature enables an MPI implementation to optimize the transfer of noncontiguous data. In practice, however, few MPI implementations implement derived datatypes in a way that performs better than what the user can achieve by manually packing data into a contiguous buffer and then calling an MPI function. In this paper, the authors present a technique for improving the performance of derived datatypes by automatically using packing algorithms that are optimized for memory-access cost. The packing algorithms use memory-optimization techniques that the user cannot apply easily without advanced knowledge of the memory architecture. The authors present performance results for a matrix-transpose example that demonstrate that their implementation of derived datatypes significantly outperforms both manual packing by the user and the existing derived-datatype code in the MPI implementation (MPICH).","hasAbstract":true,"lede":"The authors present a technique for improving the performance of derived datatypes by automatically using packing algorithms that are optimized for memory-access cost.","links":{"pdf":"https://grc.iit.edu/papers/2003/byna-2003-improving-performance-468e.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);